package io.github.astelev.around_planet.gametest;
import io.github.astelev.around_planet.space.*;
import io.github.astelev.around_planet.compat.*;
import dev.ryanhcode.sable.api.SubLevelAssemblyHelper;
import dev.ryanhcode.sable.api.sublevel.SubLevelContainer;
import dev.ryanhcode.sable.sublevel.ServerSubLevel;
import dev.ryanhcode.sable.companion.math.BoundingBox3i;
import dev.ryanhcode.sable.sublevel.storage.SubLevelRemovalReason;
import net.minecraft.gametest.framework.*;
import net.minecraft.core.BlockPos;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.entity.ChestBlockEntity;
import net.minecraft.world.item.*;
import org.joml.Vector3d;
import org.joml.Quaterniond;
import java.util.*;
@net.neoforged.neoforge.gametest.PrefixGameTestTemplate(false)
public final class MoonLandingGameTests {
 @GameTest(template="empty",templateNamespace="around_planet",batch="moonGravity",timeoutTicks=40)
 public static void lunarPlayerGravityMatchesMoonMassAndRadiusAndKeepsNoGravity(GameTestHelper h){var moon=h.getLevel().getServer().getLevel(MoonSurface.dimension());h.assertTrue(moon!=null,"No Moon dimension");var ground=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(h.getLevel());var player=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(moon);boolean old=player.isNoGravity(),oldGround=ground.isNoGravity();try{player.setNoGravity(false);ground.setNoGravity(false);double expected=ground.getGravity()*.0123/(.2724*.2724);h.assertTrue(Math.abs(player.getGravity()-expected)<1e-8,"Lunar player gravity stayed terrestrial");player.setNoGravity(true);h.assertTrue(player.getGravity()==0,"No-gravity state changed on Moon");h.succeed();}finally{player.setNoGravity(old);ground.setNoGravity(oldGround);}}

 @GameTest(template="empty",templateNamespace="around_planet",batch="moonPending",timeoutTicks=40)
 public static void pendingLunarEntryRetainsPositionAndFullVelocityAcrossSave(GameTestHelper h){var pending=new MoonLandingData();var id=UUID.randomUUID();var state=new SpaceState(new SpaceVector(1,6500,2),new SpaceVector(30,-75,10));pending.put(id,state);var saved=pending.save(new net.minecraft.nbt.CompoundTag(),h.getLevel().registryAccess());var loaded=MoonLandingData.load(saved,h.getLevel().registryAccess());h.assertTrue(state.equals(loaded.get(id)),"Pending lunar state lost during save");loaded.remove(id);h.assertTrue(!loaded.containsKey(id),"Completed landing retained pending state");h.succeed();}

 @GameTest(template="empty",templateNamespace="around_planet",batch="moonLanding",timeoutTicks=2000)
 public static void lunarLandingTransfersNativePlotInventoryAndPassengerTreeWithoutBraking(GameTestHelper h){h.runAfterDelay(5,()->start(h));}
 private static void check(boolean condition,String message){if(!condition)throw new AssertionError(message);}
 private static void start(GameTestHelper h){var source=h.getLevel();var destination=source.getServer().getLevel(MoonSurface.dimension());h.assertTrue(destination!=null,"Moon dimension missing");var container=SubLevelContainer.getContainer(source);var dest=SubLevelContainer.getContainer(destination);var data=SpaceOrbitData.get(source.getServer());var cells=SpaceCells.get(source);var orbitId=UUID.randomUUID();var pos=h.absolutePos(new BlockPos(1,2,1));source.setBlockAndUpdate(pos,Blocks.CHEST.defaultBlockState());var ship=SubLevelAssemblyHelper.assembleBlocks(source,pos,List.of(pos),new BoundingBox3i(pos.getX(),pos.getY(),pos.getZ(),pos.getX(),pos.getY(),pos.getZ()));container.addForceLoadTicket(ship,dev.ryanhcode.sable.api.sublevel.ticket.SubLevelLoadingTicketType.COMMAND_FORCED,net.minecraft.util.Unit.INSTANCE);var shipId=ship.getUniqueId();var local=ship.logicalPose().transformPositionInverse(new Vector3d(pos.getX()+.5,pos.getY()+.5,pos.getZ()+.5));var chestPos=BlockPos.containing(local.x,local.y,local.z);var item=new ItemStack(Items.DIAMOND,7);var custom=new net.minecraft.nbt.CompoundTag();var direction=new net.minecraft.nbt.ListTag();direction.add(net.minecraft.nbt.DoubleTag.valueOf(1));direction.add(net.minecraft.nbt.DoubleTag.valueOf(0));direction.add(net.minecraft.nbt.DoubleTag.valueOf(0));custom.put("example_direction",direction);item.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(custom));((ChestBlockEntity)source.getBlockEntity(chestPos)).setItem(0,item);var center=new Vector3d(28000,6144,1000);for(int x=1749;x<=1751;x++)for(int z=61;z<=63;z++){source.getChunk(x,z);source.setChunkForced(x,z,true);}var pipe=container.physicsSystem().getPipeline();pipe.teleport(ship,center,new Quaterniond());pipe.resetVelocity(ship);ship.updateBoundingBox();ship.updateLastPose();var cell=new SpaceCells.Cell(orbitId,78,center.x,center.y,center.z,0,2200,0,List.of(shipId));cells.add(source,cell);
 var sys=data.system();h.assertTrue(sys!=null,"No celestial system");var planet=MoonSurface.geometry(sys);double altitude=io.github.astelev.around_planet.PlanetConfig.MOON_LANDING.get();var lunar=new SpaceState(new SpaceVector(0,planet.radius()+altitude-1,0),new SpaceVector(30,-75,10));data.put(orbitId,new SpaceTrajectory(CelestialSystem.MOON,source.getGameTime(),new SpaceState(new SpaceVector(0,planet.radius()+altitude+200,0),SpaceVector.ZERO),0));data.navigate(orbitId,new SpaceNavigation(new PlanetScale(131072).geometry(),SpaceFrame.IDENTITY));
 for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++)destination.getChunk(x,z);
 h.runAfterDelay(10,()->{var boat=net.minecraft.world.entity.EntityType.BOAT.create(source);var pig=net.minecraft.world.entity.EntityType.PIG.create(source);boat.setPos(center.x+5,center.y+2,center.z);pig.setPos(boat.position());check(source.addFreshEntity(boat)&&source.addFreshEntity(pig),"Fixture entities failed to spawn");pig.startRiding(boat,true);boat.setNoGravity(true);pig.setNoGravity(true);var boatId=boat.getUUID();var pigId=pig.getUUID();boolean[] requested={false};
 h.succeedWhen(()->{if(!requested[0]){h.assertTrue(source.getEntity(boatId)!=null&&source.getEntity(pigId)!=null,"Waiting for source entity registration");data.put(orbitId,new SpaceTrajectory(CelestialSystem.MOON,source.getGameTime(),lunar,sys.moonMu()));requested[0]=true;}var moved=(ServerSubLevel)dest.getSubLevel(shipId);h.assertTrue(moved!=null,"Waiting for lunar destination chunks");var movedBoat=destination.getEntity(boatId);var movedPig=destination.getEntity(pigId);h.assertTrue(movedBoat!=null&&movedPig!=null&&movedPig.getVehicle()==movedBoat,"Waiting for destination entity registration");check(container.getSubLevel(shipId)==null,"Source ship remained after landing");var chest=(ChestBlockEntity)destination.getBlockEntity(chestPos);check(chest!=null&&chest.getItem(0).getCount()==7,"Native plot/inventory lost");check(chest.getItem(0).get(net.minecraft.core.component.DataComponents.CUSTOM_DATA).copyTag().equals(custom),"Item custom data was treated as world coordinates");var velocity=dest.physicsSystem().getPipeline().getLinearVelocity(moved,new Vector3d());/* Lunar gravity can accelerate descent before the asynchronous assertion observes it. Tangential speed must survive and radial speed must not be clamped. */check(Math.abs(velocity.x-lunar.velocity().x())<.1&&Math.abs(velocity.z-lunar.velocity().z())<.1&&velocity.y<=lunar.velocity().y()+.1,"Orbital speed was clamped or lost: "+velocity);check(cells.forShip(shipId)==null&&data.get(orbitId).isEmpty(),"Orbital frame retained after landing");check(destination.getRainLevel(1)==0,"Lunar weather active");dest.removeSubLevel(moved,SubLevelRemovalReason.REMOVED);for(var id:List.of(boatId,pigId)){var e=destination.getEntity(id);if(e!=null)e.discard();}cells.remove(source,cell);data.remove(orbitId);});});
 }
}
